function AuthDialog({mode,setMode,close,notify}:{mode:'login'|'signup'|'reset';setMode:(m:'login'|'signup'|'reset')=>void;close:()=>void;notify:(s:string)=>void}){const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[name,setName]=useState(''),[busy,setBusy]=useState(false);const submit=async(e:FormEvent)=>{e.preventDefault();if(!supabase){notify('Set VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY to enable authentication.');return}setBusy(true);let error:Error|null=null;let needsEmailVerification=false;if(mode==='signup'){const response=await supabase.auth.signUp({email,password,options:{data:{full_name:name}}});error=response.error;needsEmailVerification=!response.data.session}else if(mode==='reset'){const response=await supabase.auth.resetPasswordForEmail(email);error=response.error}else{const response=await supabase.auth.signInWithPassword({email,password});error=response.error}setBusy(false);if(error){notify(error.message);return}if(needsEmailVerification)notify('Check your email to verify your account.');else if(mode==='reset')notify('If the address is registered, a recovery email has been sent.');close()};return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><form className="auth-modal" onSubmit={submit}><button type="button" className="modal-close" onClick={close}><X size={18}/></button><div className="modal-mark"><LockKeyhole size={20}/></div><h2>{mode==='signup'?'Create your account':mode==='reset'?'Reset your password':'Welcome back'}</h2><p>{supabaseReady?'Your scholarship journey starts here.':'Authentication setup required: configure Supabase in frontend environment.'}</p>{mode==='signup'&&<label>Full name<input required value={name} onChange={e=>setName(e.target.value)}/></label>}<label>Email address<input type="email" required value={email} onChange={e=>setEmail(e.target.value)}/></label>{mode!=='reset'&&<label>Password<input type="password" minLength={8} required value={password} onChange={e=>setPassword(e.target.value)}/></label>}<button className="primary-button" disabled={busy}>{busy?'Please waitâ€¦':mode==='signup'?'Create account':mode==='reset'?'Send recovery link':'Sign in'} <ArrowUpRight size={15}/></button><div className="auth-links">{mode==='login'?<><button type="button" onClick={()=>setMode('signup')}>Create account</button><button type="button" onClick={()=>setMode('reset')}>Forgot password?</button></>:<button type="button" onClick={()=>setMode('login')}>Back to sign in</button>}</div></form></div>}
function normalizeCsvRow(row:any){const numbers=['min_age','max_age','annual_income_limit','min_percentage','amount_min','amount_max'];const arrays=['education_levels','eligible_courses','target_categories','required_documents'];for(const key of numbers)if(row[key]!==null&&row[key]!==undefined&&row[key]!==''){const n=Number(String(row[key]).replace(/,/g,''));row[key]=Number.isFinite(n)?n:row[key]}for(const key of arrays)if(typeof row[key]==='string')row[key]=row[key]?row[key].split(';').map((x:string)=>x.trim()).filter(Boolean):[];return row}
function parseCsv(text:string){const rows:string[][]=[];let row:string[]=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'&&quoted&&text[i+1]==='"'){cell+='"';i++}else if(c==='"')quoted=!quoted;else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(x=>x.trim()))rows.push(row);const [headers,...data]=rows;return data.map(values=>Object.fromEntries(headers.map((h,i)=>[h.trim(),values[i]?.trim()||null])))}
function ScholarshipDetails({id,close}:{id:string;close:()=>void}){const [scheme,setScheme]=useState<any>(null),[error,setError]=useState(''),[busy,setBusy]=useState(true);useEffect(()=>{let active=true;fetch(`${API}/scholarships/${id}`).then(async r=>{const d=await r.json();if(!r.ok)throw Error(d.error);return d}).then(d=>{if(active)setScheme(d)}).catch(e=>{if(active)setError(e.message)}).finally(()=>{if(active)setBusy(false)});return()=>{active=false}},[id]);const apply=()=>{if(!scheme?.official_url)return;const message=scheme.verification_status==='outdated'?'The official source changed or could not be checked recently. Review it carefully on the official portal. Continue?':'You are leaving SchemeSetu for the official scholarship application portal. SchemeSetu does not submit applications. Continue?';if(window.confirm(message))window.open(scheme.official_url,'_blank','noopener,noreferrer')};return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><section className="detail-modal"><button className="modal-close" onClick={close}><X size={18}/></button>{busy?<div className="loading"><div/></div>:error?<div className="assistant-error">{error}</div>:scheme&&<><div className="eyebrow">{scheme.government_level.toUpperCase()} SCHOLARSHIP Â· {scheme.state_name||'NATIONAL'}</div><h2>{scheme.name}</h2><p className="detail-summary">{scheme.summary||scheme.description||'No summary is available in the verified record.'}</p><div className="detail-grid">{scheme.amount_min!=null||scheme.amount_max!=null?<div><b>Benefit</b><span>{scheme.amount_min??'Unknown'}{scheme.amount_max&&scheme.amount_max!==scheme.amount_min?` to ${scheme.amount_max}`:''}</span></div>:null}<div><b>Academic year</b><span>{scheme.academic_year||'Not specified'}</span></div><div><b>Application status</b><span>{scheme.application_status}</span></div><div><b>Deadline</b><span>{scheme.application_end?new Date(scheme.application_end).toLocaleDateString('en-IN'):'Not published'}</span></div><div><b>Education levels</b><span>{scheme.education_levels?.join(', ')||'Not published'}</span></div><div><b>Eligible courses</b><span>{scheme.eligible_courses?.join(', ')||'Not published'}</span></div><div><b>Annual income limit</b><span>{scheme.annual_income_limit??'Not published'}</span></div></div>{scheme.eligibility_rules?.length>0&&<><h3>Eligibility rules</h3><ul>{scheme.eligibility_rules.filter((r:any)=>r.is_required).map((r:any,i:number)=><li key={i}>{r.field_name} {r.operator} {JSON.stringify(r.expected_value)}{r.source_note&&` â€” ${r.source_note}`}</li>)}</ul></>}{scheme.other_conditions&&<><h3>Other conditions</h3><p>{scheme.other_conditions}</p></>}{scheme.documents?.length>0||scheme.required_documents?.length>0?<><h3>Documents</h3><ul>{(scheme.documents?.length?scheme.documents:scheme.required_documents.map((document_name:string)=>({document_name,requirement_type:'required'}))).map((d:any,i:number)=><li key={i}>{d.document_name} Â· {d.requirement_type}{d.format_requirements?` Â· ${d.format_requirements}`:''}{d.condition_text?` Â· ${d.condition_text}`:''}</li>)}</ul></>:<p>Document requirements have not been published in this record.</p>}{scheme.application_procedure&&<><h3>How to apply</h3><p>{scheme.application_procedure}</p></>}{scheme.renewal_conditions&&<><h3>Renewal conditions</h3><p>{scheme.renewal_conditions}</p></>}<div className="source-note"><ShieldCheck size={15}/><span>{scheme.verification_status==='outdated'?'This record may be outdated because its source changed or could not be checked. ':'Last verified '}{scheme.last_verified_at?new Date(scheme.last_verified_at).toLocaleDateString('en-IN'):'date unavailable'}. Confirm current details at the official portal.</span></div><div className="detail-actions">{scheme.information_source_url&&<a href={scheme.information_source_url} target="_blank" rel="noopener noreferrer">Official information <ArrowUpRight size={14}/></a>}<button className="primary-button" disabled={!scheme.official_url} onClick={apply}>Apply on official portal <ArrowUpRight size={15}/></button></div></>}</section></div>}
function NotificationsPage({session,openAuth}:{session:Session|null;openAuth:()=>void}){const [items,setItems]=useState<any[]>([]),[email,setEmail]=useState(true),[push,setPush]=useState(false),[days,setDays]=useState<number[]>([30,15,7,3,1]),[message,setMessage]=useState(''),[busy,setBusy]=useState(false);const load=async()=>{if(!session||!supabase)return;const {data}=await supabase.auth.getSession();const res=await fetch(`${API}/notifications`,{headers:{Authorization:`Bearer ${data.session?.access_token||''}`}});if(!res.ok)return;const d=await res.json();setItems(d.notifications||[]);setEmail(d.preferences.email_enabled);setPush(d.preferences.push_enabled);setDays(d.preferences.reminder_days||[30,15,7,3,1])};useEffect(()=>{load()},[session]);const authHeaders=async()=>({Authorization:`Bearer ${(await supabase?.auth.getSession())?.data.session?.access_token||''}`,'Content-Type':'application/json'});const savePrefs=async()=>{setBusy(true);const h=await authHeaders();const response=await fetch(`${API}/notifications/preferences`,{method:'PUT',headers:h,body:JSON.stringify({email_enabled:email,push_enabled:push,reminder_days:days})});const d=await response.json();setMessage(response.ok?'Notification preferences saved.':d.error);setBusy(false)};const schedule=async()=>{setBusy(true);const h=await authHeaders();const response=await fetch(`${API}/notifications/schedule`,{method:'POST',headers:h});const d=await response.json();setMessage(response.ok?`${d.scheduled} verified deadline reminders scheduled.`:d.error);setBusy(false);await load()};const enablePush=async()=>{if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window)){setMessage('This browser does not support web push.');return}const vapid=import.meta.env.VITE_WEB_PUSH_PUBLIC_KEY as string|undefined;if(!vapid){setMessage('Set VITE_WEB_PUSH_PUBLIC_KEY and the matching backend VAPID keys first.');return}const permission=await Notification.requestPermission();if(permission!=='granted'){setMessage('Browser notification permission was not granted.');return}const registration=await navigator.serviceWorker.register('/sw.js');const applicationServerKey=Uint8Array.from(atob(vapid.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));const subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey});const h=await authHeaders();const response=await fetch(`${API}/notifications/push-subscription`,{method:'POST',headers:h,body:JSON.stringify(subscription)});setMessage(response.ok?'Web push is enabled on this device.':'Could not save this device subscription.');if(response.ok){setPush(true);const prefs=await fetch(`${API}/notifications/preferences`,{method:'PUT',headers:h,body:JSON.stringify({email_enabled:email,push_enabled:true,reminder_days:days})});if(!prefs.ok)setMessage('Push subscription saved, but preferences could not be updated.')}};const read=async(id:string)=>{const h=await authHeaders();await fetch(`${API}/notifications/${id}/read`,{method:'PATCH',headers:h});setItems(items.map(x=>x.id===id?{...x,read_at:new Date().toISOString()}:x))};if(!session)return <section className="module"><div className="eyebrow">DEADLINE TRACKER</div><h2>Notifications</h2><p>Sign in to set scholarship reminders.</p><button className="primary-button" onClick={openAuth}>Sign in <ArrowUpRight size={15}/></button></section>;return <section className="module"><div className="eyebrow">DEADLINE TRACKER</div><h2>Notifications</h2><p>Deadline reminders are created only from verified scholarship dates. Confirm every deadline on its official portal.</p><div className="preference-box"><h3 className="subheading">Reminder preferences</h3><label className="preference"><input type="checkbox" checked={email} onChange={e=>setEmail(e.target.checked)}/> Email reminders</label><label className="preference"><input type="checkbox" checked={push} onChange={e=>setPush(e.target.checked)}/> Web push reminders</label><span className="reminder-caption">Remind me</span><div className="reminder-days">{[30,15,7,3,1].map(d=><label key={d}><input type="checkbox" checked={days.includes(d)} onChange={e=>setDays(e.target.checked?[...days,d].sort((a,b)=>b-a):days.filter(x=>x!==d))}/>{d} days</label>)}</div><div className="notification-actions"><button className="primary-button" disabled={busy} onClick={savePrefs}>Save preferences</button><button className="secondary-button" disabled={busy} onClick={schedule}>Refresh saved deadline reminders</button><button className="secondary-button" onClick={enablePush}>Enable push on this device</button></div></div>{message&&<div className="admin-message">{message}</div>}<h3 className="subheading">Your reminders</h3>{items.length?items.map(n=><article className={n.read_at?'notification-row read':'notification-row'} key={n.id} onClick={()=>!n.read_at&&read(n.id)}><div><b>{n.payload?.title||n.notification_type.replaceAll('_',' ')}</b><span>{n.payload?.body||''}</span><small>{n.scheduled_for?`Scheduled ${new Date(n.scheduled_for).toLocaleString('en-IN')}`:`Sent ${n.sent_at?new Date(n.sent_at).toLocaleString('en-IN'):'pending'}`}</small></div>{n.scholarships?.official_url&&<a href={n.scholarships.official_url} target="_blank" rel="noreferrer">Official scheme <ArrowUpRight size={13}/></a>}</article>):<div className="empty"><Bell size={22}/><strong>No reminders scheduled</strong><span>Save scholarships, then refresh reminders using verified deadlines.</span></div>}</section>}
function AdminPage(){const [overview,setOverview]=useState<any>(null),[pending,setPending]=useState<any[]>([]),[sourceId,setSourceId]=useState(''),[records,setRecords]=useState<any[]>([]),[sourceForm,setSourceForm]=useState({name:'',government_level:'state',region_name:'',source_url:'',department:'',crawl_permitted:false}),[message,setMessage]=useState(''),[busy,setBusy]=useState(false);const token=async()=> (await supabase?.auth.getSession())?.data.session?.access_token||'';const headers=async()=>({Authorization:`Bearer ${await token()}`,'Content-Type':'application/json'});const load=async()=>{const h=await headers();const [o,p]=await Promise.all([fetch(`${API}/admin/overview`,{headers:h}),fetch(`${API}/admin/scholarships?status=pending`,{headers:h})]);if(o.ok)setOverview(await o.json());if(p.ok)setPending((await p.json()).data||[])};useEffect(()=>{load()},[]);const addSource=async(e:FormEvent)=>{e.preventDefault();const h=await headers();const response=await fetch(`${API}/admin/sources`,{method:'POST',headers:h,body:JSON.stringify({...sourceForm,region_name:sourceForm.region_name||null})});const d=await response.json();setMessage(response.ok?'Official source added.':d.error);if(response.ok){setSourceForm({name:'',government_level:'state',region_name:'',source_url:'',department:'',crawl_permitted:false});await load()}};const importRecords=async()=>{if(!sourceId||!records.length)return;setBusy(true);const h=await headers();const r=await fetch(`${API}/admin/import`,{method:'POST',headers:h,body:JSON.stringify({sourceId,records})});const d=await r.json();setMessage(r.ok?`Added ${d.added}; duplicates ${d.duplicates}; rows needing attention ${d.issues.length}.`:d.error);setBusy(false);await load()};const checkSource=async(id:string)=>{const h=await headers();const r=await fetch(`${API}/admin/sources/${id}/check`,{method:'POST',headers:h});const d=await r.json();setMessage(r.ok?`Source check status: ${d.status}.`:d.error);await load()};const rebuildEmbeddings=async()=>{setBusy(true);let page=1,indexed=0,failed=0;try{while(true){const h=await headers();const response=await fetch(`${API}/admin/embeddings/rebuild`,{method:'POST',headers:h,body:JSON.stringify({page})});const d=await response.json();if(!response.ok)throw Error(d.error||'Indexing failed');indexed+=d.indexed;failed+=d.failed;if(!d.nextPage)break;page=d.nextPage}setMessage(`Semantic index rebuilt: ${indexed} schemes indexed, ${failed} failed.`)}catch(e){setMessage(e instanceof Error?e.message:'Could not rebuild semantic index.')}finally{setBusy(false)}};const verify=async(id:string,status:string)=>{const h=await headers();const r=await fetch(`${API}/admin/scholarships/${id}/verification`,{method:'PATCH',headers:h,body:JSON.stringify({status})});const d=await r.json();setMessage(r.ok?`Record marked ${status}.`:d.error);await load()};const edit=async(s:any)=>{const raw=window.prompt('Edit scheme JSON fields. Updates return the record to pending review.',JSON.stringify({name:s.name,summary:s.summary,government_level:s.government_level,state_name:s.state_name,official_url:s.official_url,application_end:s.application_end,amount_min:s.amount_min,amount_max:s.amount_max},null,2));if(!raw)return;try{const h=await headers();const r=await fetch(`${API}/admin/scholarships/${s.id}`,{method:'PUT',headers:h,body:raw});const d=await r.json();setMessage(r.ok?'Record updated and returned to pending review.':d.error);await load()}catch{setMessage('Edit data must be valid JSON.')}};const remove=async(id:string)=>{if(!window.confirm('Permanently delete this scholarship record?'))return;const h=await headers();const r=await fetch(`${API}/admin/scholarships/${id}`,{method:'DELETE',headers:h});setMessage(r.ok?'Record deleted.':'Could not delete record.');await load()};return <section className="module admin-page"><div className="eyebrow">DATA GOVERNANCE</div><h2>Administrator dashboard</h2><p>Only verified records appear in student search. Imports enter as pending and need source review.</p>{message&&<div className="admin-message">{message}</div>}{overview&&<><div className="admin-metrics">{[['Total',overview.coverage.total],['Central',overview.coverage.central],['States',overview.coverage.state],['UTs',overview.coverage.ut],['Verified',overview.coverage.verified],['Pending',overview.coverage.pending],['Outdated',overview.coverage.outdated],['Open',overview.coverage.open],['Expired',overview.coverage.expired]].map(([label,value])=><div key={label}><b>{value}</b><span>{label}</span></div>)}</div><div className="coverage-chart" role="img" aria-label="Scholarship coverage by government level and verification status"><Suspense fallback={<div className="chart-loading"/>}><CoverageChart coverage={overview.coverage}/></Suspense></div><h3 className="subheading">Regional source coverage</h3><div className="region-grid">{overview.regional.map((r:any)=><div key={r.region}><span>{r.region}</span><small>{r.sources} source - {r.schemes} schemes</small></div>)}</div><h3 className="subheading">Registered official sources</h3>{overview.sources.map((s:any)=><div className="source-row" key={s.id}><div><b>{s.name}</b><span>{s.region_name||s.government_level} - {s.source_url}</span></div><div><small>{s.last_checked_at?`Checked ${new Date(s.last_checked_at).toLocaleDateString('en-IN')} Â· ${s.last_status||'status unknown'}`:'Not checked yet'}</small>{s.crawl_permitted&&<button className="source-check" onClick={()=>checkSource(s.id)}>Check now</button>}</div></div>)}</>}
<h3 className="subheading">Register an official source</h3><form className="source-form" onSubmit={addSource}><input required placeholder="Source name" value={sourceForm.name} onChange={e=>setSourceForm({...sourceForm,name:e.target.value})}/><select value={sourceForm.government_level} onChange={e=>setSourceForm({...sourceForm,government_level:e.target.value})}><option value="central">Central</option><option value="state">State</option><option value="ut">Union territory</option><option value="private">Private / corporate</option></select><input placeholder="Region (if applicable)" value={sourceForm.region_name} onChange={e=>setSourceForm({...sourceForm,region_name:e.target.value})}/><input required type="url" placeholder="Official HTTPS source URL" value={sourceForm.source_url} onChange={e=>setSourceForm({...sourceForm,source_url:e.target.value})}/><input placeholder="Department" value={sourceForm.department} onChange={e=>setSourceForm({...sourceForm,department:e.target.value})}/><label className="source-crawl"><input type="checkbox" checked={sourceForm.crawl_permitted} onChange={e=>setSourceForm({...sourceForm,crawl_permitted:e.target.checked})}/> Allow scheduled public checks when robots.txt permits</label><button className="primary-button">Add source</button></form>
<h3 className="subheading">Semantic search index</h3><p className="import-note">Build or refresh pgvector embeddings from verified scholarship records. Gemini API key is required.</p><button className="secondary-button" disabled={busy} onClick={rebuildEmbeddings}>{busy?'Indexing verified recordsâ€¦':'Rebuild semantic index'}</button>
<h3 className="subheading">Import scholarship data</h3><p className="import-note">Choose a JSON array or CSV with headers matching scholarship fields. Imported records remain pending until you verify them.</p><select value={sourceId} onChange={e=>setSourceId(e.target.value)}><option value="">Select registered source</option>{overview?.sources.map((s:any)=><option key={s.id} value={s.id}>{s.name} â€” {s.region_name||s.government_level}</option>)}</select><input type="file" accept=".json,.csv,application/json,text/csv" onChange={async e=>{const f=e.target.files?.[0];if(!f)return;const text=await f.text();try{const parsed=f.name.toLowerCase().endsWith('.csv')?parseCsv(text):JSON.parse(text);setRecords((Array.isArray(parsed)?parsed:parsed.records||[]).map(normalizeCsvRow));setMessage('Import file loaded. Review source and submit when ready.')}catch{setMessage('File could not be parsed as JSON or CSV.')}}}/><button disabled={busy||!records.length||!sourceId} className="primary-button" onClick={importRecords}>{busy?'Importingâ€¦':`Import ${records.length} records`}</button>
<h3 className="subheading">Pending source review ({pending.length})</h3>{pending.map((s:any)=><div className="review-row" key={s.id}><div><b>{s.name}</b><span>{s.state_name||s.government_level} - <a href={s.information_source_url} target="_blank" rel="noreferrer">source</a> - <a href={s.official_url||undefined} target="_blank" rel="noreferrer">application</a></span></div><button onClick={()=>edit(s)}>Edit</button><button onClick={()=>remove(s.id)} className="reject">Delete</button><button onClick={()=>verify(s.id,'verified')}>Verify</button><button className="reject" onClick={()=>verify(s.id,'rejected')}>Reject</button></div>)}</section>}
function documentMatches(type:string,name:string){const n=name.toLowerCase(),t=type.toLowerCase();const aliases:Record<string,string[]>={aadhaar:['aadhaar','aadhar','uidai'],income_certificate:['income certificate','income proof'],marksheet:['marksheet','mark sheet','marks card'],pan:['pan card','permanent account'],student_id:['student id','identity card','bonafide','institution id']};return(aliases[t]||[t.replaceAll('_',' ')]).some(alias=>n.includes(alias))}
function DocumentsPage({session,openAuth}:{session:Session|null;openAuth:()=>void}){const [file,setFile]=useState<File|null>(null),[items,setItems]=useState<any[]>([]),[busy,setBusy]=useState(false),[error,setError]=useState(''),[consent,setConsent]=useState(false),[schemes,setSchemes]=useState<{id:string;name:string}[]>([]),[schemeId,setSchemeId]=useState(''),[requirements,setRequirements]=useState<any[]>([]);const load=async()=>{if(!session||!supabase)return;const {data}=await supabase.from('student_documents').select('id,document_type,uploaded_at,masked_fields,document_analysis(*)').eq('user_id',session.user.id).order('uploaded_at',{ascending:false});setItems(data||[])};useEffect(()=>{load();if(!session||!supabase)return;let all:{id:string;name:string}[]=[];(async()=>{for(let offset=0;;offset+=1000){const {data}=await supabase.from('scholarships').select('id,name').eq('verification_status','verified').range(offset,offset+999);if(!data)break;all.push(...data);if(data.length<1000)break}setSchemes(all)})()},[session]);useEffect(()=>{if(!schemeId||!supabase){setRequirements([]);return}supabase.from('scholarship_documents').select('*').eq('scholarship_id',schemeId).then(({data})=>setRequirements(data||[]))},[schemeId]);const analyze=async(e:FormEvent)=>{e.preventDefault();if(!session||!supabase||!file)return;if(!['application/pdf','image/png','image/jpeg'].includes(file.type)||file.size>8*1024*1024){setError('Choose a PDF, PNG, or JPEG file under 8 MB.');return}setBusy(true);setError('');const path=`${session.user.id}/${crypto.randomUUID()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const upload=await supabase.storage.from('student-documents').upload(path,file,{contentType:file.type,upsert:false});if(upload.error){setError(upload.error.message);setBusy(false);return}const {data:auth}=await supabase.auth.getSession();try{const response=await fetch(`${API}/documents/analyze`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${auth.session?.access_token||''}`},body:JSON.stringify({path,consent:true})});const result=await response.json();if(!response.ok)throw Error(result.error||'Analysis failed.');await load();setFile(null);setConsent(false)}catch(err){setError(err instanceof Error?err.message:'Document analysis failed.');await supabase.storage.from('student-documents').remove([path])}finally{setBusy(false)}};const downloadChecklist=()=>{const text=requirements.map((r:any)=>`[ ] ${r.document_name} (${r.requirement_type})${r.format_requirements?` - ${r.format_requirements}`:''}`).join('\n');const blob=new Blob([text],{type:'text/plain'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='scholarship-document-checklist.txt';a.click();URL.revokeObjectURL(url)};const remove=async(id:string)=>{if(!window.confirm('Permanently delete this document and its analysis?'))return;const {data}=await supabase?.auth.getSession()||{data:{session:null}};const response=await fetch(`${API}/documents/${id}`,{method:'DELETE',headers:{Authorization:`Bearer ${data.session?.access_token||''}`}});if(response.ok)await load();else setError('Could not delete this document.')};if(!session)return <section className="module"><div className="eyebrow">PRIVATE DOCUMENT ANALYSIS</div><h2>Document analyzer</h2><p>Sign in to upload documents to your private account.</p><button className="primary-button" onClick={openAuth}>Sign in <ArrowUpRight size={15}/></button></section>;return <section className="module"><div className="eyebrow">PRIVATE DOCUMENT ANALYSIS</div><h2>Your documents</h2><p>Files stay in private storage. OCR checks readability and masks sensitive numbers; it does not authenticate documents with the government.</p><form className="upload-form" onSubmit={analyze}><label className="upload-control">Select PDF, PNG, or JPEG<input type="file" accept="application/pdf,image/png,image/jpeg" onChange={e=>setFile(e.target.files?.[0]||null)}/></label>{file&&<span className="file-name">{file.name} - {(file.size/1024/1024).toFixed(2)} MB</span>}<label className="consent"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/> I consent to temporary OCR processing of this file. The raw file is not sent to the AI assistant.</label><button disabled={!file||!consent||busy} className="primary-button">{busy?'Analyzing documentâ€¦':'Upload and analyze'}</button>{error&&<p className="assistant-error">{error}</p>}</form><h3 className="subheading">Scholarship document checklist</h3><select className="checklist-select" value={schemeId} onChange={e=>setSchemeId(e.target.value)}><option value="">Choose a verified scholarship</option>{schemes.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select>{schemeId&&requirements.length>0&&<button type="button" className="secondary-button checklist-download" onClick={downloadChecklist}>Download checklist</button>}{schemeId&&<div className="checklist">{requirements.length?requirements.map((r:any)=><div key={r.id}><span>{r.document_name}</span><span>{items.some(x=>documentMatches(x.document_type,r.document_name))?'Available':'Not matched'}</span></div>):<p>No verified document checklist is recorded for this scholarship yet.</p>}</div>}<h3 className="subheading">Uploaded documents</h3>{items.length?items.map(item=><article className="document-row" key={item.id}><div><strong>{item.document_type.replaceAll('_',' ')}</strong><span>{Object.values(item.masked_fields||{}).join(' - ')||'No sensitive number detected'}</span><small>{new Date(item.uploaded_at).toLocaleDateString('en-IN')} - {item.document_analysis?.[0]?.extracted_fields?.readable?'Readable':'Needs review'} - OCR readability only</small>{item.document_analysis?.[0]?.missing_fields?.map((m:string)=><small key={m}>Missing: {m}</small>)}{item.document_analysis?.[0]?.warnings?.map((w:string)=><small key={w}>{w}</small>)}</div><button className="delete-document" onClick={()=>remove(item.id)}>Delete</button></article>):<div className="empty"><Database size={22}/><strong>No documents yet</strong><span>Uploaded documents will appear here privately.</span></div>}</section>}
function AssistantPage(){
 const [question,setQuestion]=useState(''),[answer,setAnswer]=useState(''),[sources,setSources]=useState<{index:number;name:string;url:string|null;lastVerified:string|null}[]>([]),[busy,setBusy]=useState(false),[error,setError]=useState(''),[language,setLanguage]=useState('English'),[recognizing,setRecognizing]=useState(false),[aiConfigured,setAiConfigured]=useState<boolean|null>(null),[sourceMode,setSourceMode]=useState('');
 const languageTags:Record<string,string>={English:'en-IN',Hindi:'hi-IN',Kannada:'kn-IN',Tamil:'ta-IN',Telugu:'te-IN',Bengali:'bn-IN',Marathi:'mr-IN'};
 const suggestions=['Which scholarships are open now?','I am an undergraduate student','Show scholarships for students with disabilities'];
 useEffect(()=>{fetch(`${API}/health`).then(r=>r.json()).then(d=>setAiConfigured(Boolean(d.aiConfigured))).catch(()=>setAiConfigured(false))},[]);
 const ask=async(e:FormEvent)=>{e.preventDefault();if(!question.trim())return;setBusy(true);setError('');setAnswer('');setSources([]);try{const response=await fetch(`${API}/assistant`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:question.trim(),language})});const data=await response.json();if(!response.ok)throw Error(data.error||'Could not answer the question.');setAnswer(data.answer);setSources(data.sources||[]);setSourceMode(data.mode||'nvidia')}catch(err){setError(err instanceof Error?err.message:'Assistant unavailable. Check that the API is running.')}finally{setBusy(false)}};
 const voiceInput=()=>{const w=window as any;const Recognition=w.SpeechRecognition||w.webkitSpeechRecognition;if(!Recognition){setError('Voice input is not supported by this browser.');return}const recognition=new Recognition();recognition.lang=languageTags[language]||'en-IN';recognition.interimResults=false;recognition.onresult=(event:any)=>setQuestion((event.results?.[0]?.[0]?.transcript||'').trim());recognition.onerror=()=>setError('Could not capture speech. Check microphone permission and try again.');recognition.onend=()=>setRecognizing(false);setRecognizing(true);recognition.start()};
 const speak=()=>{if(!('speechSynthesis'in window)){setError('Spoken responses are not supported by this browser.');return}window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(answer);utterance.lang=languageTags[language]||'en-IN';window.speechSynthesis.speak(utterance)};
 return <section className="module assistant">
  <div className="assistant-heading"><div className="assistant-mark"><MessageSquare size={22}/></div><div><div className="eyebrow">SCHOLARSHIP GUIDE</div><h2>Ask SchemeSetu</h2><p>Get clear answers about schemes, deadlines, and where to apply.</p></div></div>
  <div className={aiConfigured?'assistant-status ready':'assistant-status local'}><span className="status-dot"/><div><strong>{aiConfigured?'NVIDIA AI is connected':aiConfigured===null?'Checking assistant...':'Scheme guide is ready'}</strong><small>{aiConfigured?'Answers are grounded in scholarship records and link to their official sources.':aiConfigured===null?'Checking the assistant service.':'Local scheme answers are available. Add NVIDIA_API_KEY to the root .env file to enable live AI answers.'}</small></div></div>
  <div className="assistant-tools"><label className="language-picker">Reply in<select value={language} onChange={e=>setLanguage(e.target.value)}>{Object.keys(languageTags).map(x=><option key={x}>{x}</option>)}</select></label><div className="assistant-suggestions" aria-label="Suggested questions">{suggestions.map(s=><button type="button" key={s} onClick={()=>setQuestion(s)}>{s}</button>)}</div></div>
  <form className="assistant-form" onSubmit={ask}><textarea value={question} onChange={e=>setQuestion(e.target.value)} maxLength={2000} minLength={4} placeholder="Ask about a scholarship, your course, state, or application deadline..." required/><div className="assistant-actions"><button className="primary-button" disabled={busy}>{busy?'Looking up schemes...':'Ask a question'} <ArrowUpRight size={15}/></button><button type="button" className="secondary-button" onClick={voiceInput}>{recognizing?'Listening...':'Use voice input'}</button><span className="assistant-hint">SchemeSetu does not submit applications.</span></div></form>
  {error&&<div className="assistant-error" role="alert">{error}</div>}
  {answer&&<div className="assistant-answer"><div className="answer-heading"><strong>SchemeSetu</strong><span className={sourceMode==='local'?'answer-mode local':'answer-mode'}>{sourceMode==='local'?'Local catalog':'NVIDIA AI'}</span></div><p>{answer}</p><button className="secondary-button" onClick={speak}>Read answer aloud</button>{sources.length>0&&<div className="assistant-sources"><b>Official sources</b>{sources.map(s=><a key={s.index} href={s.url||undefined} target="_blank" rel="noopener noreferrer">[{s.index}] {s.name} {s.lastVerified&&`- checked ${new Date(s.lastVerified).toLocaleDateString('en-IN')}`}<ArrowUpRight size={13}/></a>)}</div>}</div>}
 </section>
}
function ApplicationTracker({scholarshipId,userId,notify}:{scholarshipId:string;userId:string;notify:(s:string)=>void}){const [status,setStatus]=useState('');useEffect(()=>{supabase?.from('applications').select('status').eq('user_id',userId).eq('scholarship_id',scholarshipId).maybeSingle().then(({data})=>setStatus(data?.status||''))},[scholarshipId,userId]);const update=async(value:string)=>{if(!supabase)return;const {error}=await supabase.from('applications').upsert({user_id:userId,scholarship_id:scholarshipId,status:value,updated_at:new Date().toISOString()},{onConflict:'user_id,scholarship_id'});if(error)notify(error.message);else{setStatus(value);notify('Application status updated')}};return <select aria-label="Application progress" className="application-status" value={status} onChange={e=>update(e.target.value)}><option value="">Track application</option><option value="interested">Interested</option><option value="preparing_documents">Preparing documents</option><option value="ready_to_apply">Ready to apply</option><option value="applied">Applied</option><option value="under_review">Under review</option><option value="approved">Approved</option><option value="rejected">Rejected</option></select>}
function ProfilePage({profile,setProfile}:{profile:StudentProfile;setProfile:(p:StudentProfile)=>void}){const categories=Array.isArray(profile.social_categories)?profile.social_categories:[];const field=(key:string,label:string,type='text')=><label>{label}<input type={type} value={String(profile[key]??'')} onChange={e=>setProfile({...profile,[key]:type==='number'?(e.target.value?Number(e.target.value):null):e.target.value})}/></label>;return <section className="module"><div className="eyebrow">YOUR DETAILS ? STORED ON THIS DEVICE</div><h2>Student profile</h2><p>Add only the details you want to use for eligibility matching. Your profile stays in this browser and is not uploaded.</p><form className="profile-form" onSubmit={e=>{e.preventDefault();localStorage.setItem('schemesetu-profile',JSON.stringify(profile))}}>{field('full_name','Name (optional)')}{field('date_of_birth','Date of birth','date')}<label>Gender<select value={String(profile.gender??'')} onChange={e=>setProfile({...profile,gender:e.target.value})}><option value="">Prefer not to say</option><option>Female</option><option>Male</option><option>Other</option></select></label><label>State / UT<select value={String(profile.region_name??'')} onChange={e=>setProfile({...profile,region_name:e.target.value})}><option value="">Select region</option>{states.map(x=><option key={x}>{x}</option>)}</select></label>{field('district','District')}{field('education_level','Education level (e.g. Undergraduate)')}{field('course','Course')}{field('stream','Stream')}{field('academic_year','Current academic year')}{field('institution_name','Institution name')}{field('institution_state','Institution state')}{field('percentage','Previous exam percentage','number')}{field('family_income','Annual family income (INR)','number')}<label>Social category<select value={String(categories[0]??'')} onChange={e=>setProfile({...profile,social_categories:e.target.value?[e.target.value]:[]})}><option value="">Prefer not to say</option>{['General','SC','ST','OBC','EWS','Minority'].map(x=><option key={x}>{x}</option>)}</select></label>{field('institution_type','Institution type')}{field('academic_status','Current academic status')}{field('nationality','Nationality')}{field('parent_occupation','Parent / guardian occupation')}<label>Residence<select value={String(profile.residence_type??'')} onChange={e=>setProfile({...profile,residence_type:e.target.value})}><option value="">Prefer not to say</option><option value="rural">Rural</option><option value="urban">Urban</option></select></label>{['income_certificate_available','disability','orphan','first_generation','previous_scholarship'].map((key,i)=><label className="check-label" key={key}><input type="checkbox" checked={Boolean(profile[key])} onChange={e=>setProfile({...profile,[key]:e.target.checked})}/> {['Income certificate available','I have a disability','I am an orphan','First-generation learner','Received a scholarship before'][i]}</label>)}<label>Hostel / day scholar<select value={String(profile.residence_mode??'')} onChange={e=>setProfile({...profile,residence_mode:e.target.value})}><option value="">Prefer not to say</option><option value="hostel">Hostel</option><option value="day_scholar">Day scholar</option></select></label><button className="primary-button"><Save size={16}/> Save on this device</button><button type="button" className="secondary-button" onClick={()=>{localStorage.removeItem('schemesetu-profile');setProfile({})}}>Clear profile</button></form></section>}
function EligibilityPage({profile,setProfile}:{profile:StudentProfile;setProfile:(p:StudentProfile)=>void}){const [items,setItems]=useState<{scholarship:Scheme;result:{status:string;matched:number;failed:string[];unknown:string[]}}[]>([]);const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const field=(key:string,label:string,type='text')=><label>{label}<input type={type} value={String(profile[key]??'')} onChange={e=>setProfile({...profile,[key]:type==='number'?(e.target.value?Number(e.target.value):null):e.target.value})}/></label>;const booleanField=(key:string,label:string)=><label>{label}<select value={profile[key]===true?'yes':profile[key]===false?'no':''} onChange={e=>setProfile({...profile,[key]:e.target.value===''?undefined:e.target.value==='yes'})}><option value="">Not sure / skip</option><option value="yes">Yes</option><option value="no">No</option></select></label>;const evaluate=async()=>{setBusy(true);setMessage('');try{const response=await fetch(`${API}/eligibility/schemes`);const data=await response.json();if(!response.ok)throw Error('Could not load scholarship rules.');const schemes:Scheme[]=data;const matches=schemes.map(s=>({scholarship:s,result:evaluateEligibility(profile,(s as any).eligibility_rules||[])}));setItems(matches.sort((a,b)=>a.result.status==='eligible'?-1:b.result.status==='eligible'?1:0));if(!schemes.length)setMessage('No scholarship records are available yet.')}catch{setMessage('Could not load eligibility rules. Check that the API is running.')}finally{setBusy(false)}};return <section className="module"><div className="eyebrow">PRIVATE, ON THIS DEVICE</div><h2>Check your eligibility</h2><p>Enter only the details you want to check. They stay in this browser and are not sent to an account. Matches are an initial guide, not an official decision.</p><form className="profile-form eligibility-form" onSubmit={e=>{e.preventDefault();void evaluate()}}>{field('family_income','Annual family income (INR)','number')}<label>Education level<select value={String(profile.education_level??'')} onChange={e=>setProfile({...profile,education_level:e.target.value})}><option value="">Select education level</option>{['School','Diploma','Undergraduate','Postgraduate','Doctoral'].map(x=><option key={x}>{x}</option>)}</select></label>{booleanField('top_20_percentile','Are you in the top 20% of your board merit list?')}{booleanField('regular_course','Are you enrolled in a regular course?')}{booleanField('receiving_other_scholarship','Do you receive another scholarship or fee reimbursement?')}{booleanField('disability','Are you a student with a disability?')}<button className="primary-button" disabled={busy}>{busy?'Checking schemes...':'Check matching scholarships'} <ClipboardCheck size={16}/></button></form>{message&&<p>{message}</p>}{items.length>0&&<div className="match-list">{items.map(x=><article key={x.scholarship.id}><div><strong>{x.scholarship.name}</strong><span className={x.result.status==='eligible'?'match-good':'match-unknown'}>{x.result.status==='eligible'?'Matches known rules':x.result.status==='not_eligible'?'Does not match known rules':x.result.unknown.includes('eligibility rules')?'Criteria need review':'Add information'}</span></div><p>{x.result.unknown.length?`Needs information: ${x.result.unknown.join(', ')}`:x.result.failed.length?`Review: ${x.result.failed.join(', ')}`:'Known required rules match. Check the official criteria before applying.'}</p>{x.scholarship.official_url&&<a href={x.scholarship.official_url} target="_blank" rel="noopener noreferrer">Official scheme page <ArrowUpRight size={13}/></a>}</article>)}</div>}</section>}
export default App;





































